# Slide prose. Supporting detail from the complete R2 content is retained in notes.
Q={
7:[('① 怎么发现的','DroneRFa的12机型基线用10 ms时频图与ResNet18，整体准确率85.4%，Matrice 100仅71.0%；漏检随时间周期性出现。'),('② 怎么证实的','长时时频图显示：每14 ms才有1–2 ms强突发，10 ms窗约29%落在间隙；15、20 ms窗无此空窗。'),('③ 依据','DroneRFa表4按机型统计周期，4.3节讨论短片段缺少完整特征。M100的14 ms为本项目测量。'),('④ 怎么解决的','依导师规则先看整条录音，剔除缺少特征或明显异常的窗，再比较窗长。'),('⑤ 结果与留下的问题','解释了周期性漏检。→ M300仅34.8%，还不能用窗长解释。')],
8:[('① 怎么发现的','M300仅34.8%，134段误判为Phantom 4 Pro RTK。S0110前70段全对，后90段仅对31段。'),('② 怎么证实的','补看5.8 GHz否定了“换频段”猜测。实际是信道中心2456→2409 MHz；不重训、只平移20–40 MHz，原本100%降至0–4%，挪回低端片段则34%→59%。遮挡2400–2425 MHz还使Mavic 3由96%降至9%。'),('③ 依据','Geirhos 2020：标准测试高分、换条件却失效的规则属于捷径，同分布测试不足以发现。'),('⑤ 结果与留下的问题','首次证实位置或环境线索。→ 转实测后，每个结论都要配“替换线索”的对照。')],
11:[('① 怎么发现的','截频前发现贯穿录音的窄线，逐录音、逐频点统计，出现率≥90%才列为稳定谱线。'),('② 怎么证实的','A的2.4 GHz有2400/2426.88/2457.60 MHz，5.8 GHz有5800/5740 MHz；偏移与fs成整数比。B仅中心尖峰，导师确认为本振泄漏。'),('③ 依据','WiSig证明模型会学习接收机信息，谱线可能随来源变成标签线索。'),('④ 怎么解决的','非中心线正弦对消通过率≥96%；中心尖峰约47 kHz，残留15–18 dB，改陷波。各类样本使用同一陷波表。'),('⑤ 结果与留下的问题','避免来源特有的凹坑处理。→ 来源与标签本身是否绑定？')],
12:[('① 怎么发现的','整理训练集发现：背景100%来自B，无人机93%/89%来自A（2.4/5.8 GHz）。2.4 GHz背景仅8.8 s，类比1:13.8。'),('② 怎么证实的','只取3个无关无人机的底噪特征做逻辑回归，虚警0%，实验室检出93.2%，城区仅0.9%；同接收机、同地同日对照平衡准确率0.51，说明高分只是在认来源。'),('③ 依据','WiSig做接收机留出；Geirhos建议用分类器识别数据分布差异。'),('④ 怎么解决的','不能补录，改为分来源报告，并强制替换线索对照。'),('⑤ 结果与留下的问题','来源混杂风险已证实。→ 训练后检验模型实际用了哪条线索。')],
13:[('① 怎么发现的','首轮20 ms训练、3种子虚警0.4%/0.6%，但2.4 GHz实验室召回92%、城区仅58%。'),('② 怎么证实的','同批样本、相同功率比，只换背景：0 dB时白噪声检出90%、城区57%；城区样本加白噪反升79%–88%。5.8 GHz两种背景近同（100% vs 98%）。'),('③ 依据','Geirhos的分布外检验：替换背景而保留信号，检验判断依据。'),('④ 怎么解决的','先更正假设：5.8 GHz模型未用接收机差异；2.4 GHz真正利用的是WiFi环境线索。'),('⑤ 结果与留下的问题','→ 需补“有WiFi的无人机”和“无WiFi背景”，但两种都缺且不能补录。')],
14:[('① 怎么发现的','A没录背景，模型对A无信号数据虚警100%，19段真实安静录音也全判无人机。'),('② 怎么证实的','陷波白噪声被3种子全判无人机；不陷波仅1种子误报，填坑后两种子误报0%和1.5%。原因是空频段加陷波坑，并非接收机指纹。'),('④ 怎么解决的','57条录音的2342.6–2393.5 MHz无发射源，取共轭镜像到2405–2455 MHz；按≤0.3 dB检验，61块剔除6块。'),('⑤ 结果与留下的问题','A虚警100%→0%（0/1287，95%上界0.23%），城区虚警不变0.42%，召回58%→62%。→ WiFi仍未解决。')],
15:[('③ 依据','Glüge 2024先归一化，再按SNR混合暗室无人机和WiFi/蓝牙，将背景和专录底噪作为Noise类；外场平衡准确率0.807–0.986。'),('④ 怎么解决的','各3种子，功率比−5到15 dB随机取。La只给无人机叠城区背景；Lb也给实验室背景叠加，其他设置相同。'),('⑤ 结果与留下的问题','La召回62%→88%，却使叠加集虚警7.3%→24%，学出“A底噪+WiFi=无人机”。Lb虚警1.9%、召回81%，mavic2为20%→53%，mini3pro为21%→77%。因此采用Lb。填陷波坑后白噪声虚警5%→0%，其余无可靠变化。→ 接着检验窗长和特征。')],
18:[('① 怎么发现的','R/Z/F/F5×两频段×3种子，共24次训练，并做整体、单特征打乱和置零检验。'),('② 怎么证实的','2.4 GHz的F虚警2.5%/1.55%、城区召回89.5%，但相对Z的三种子方向不一致，不算提升。整体打乱后虚警+5.5个百分点，同标签内打乱仅+0.4。'),('③ 依据','5.8 GHz来源突发特征AUC近1，可能泄露来源；Z比R高来自头部结构，不能归因于特征。'),('⑤ 结果与留下的问题','5.8 GHz召回Z 94.9%→F 89.2%→F5 86.2%，城区evo2pro_v3为52%→21%/19%。融合不宜定为基线，待与导师讨论。→ 回查固定频带是否截掉信号。')],
19:[('① 怎么发现的','固定2405–2455 MHz截不全：城区mavic2的99%在2460–2475 MHz，evo2pro_v3约70%在外；实验室三机型约80%在2455–2460 MHz。'),('④ 怎么解决的','用A背景与噪声校准k=6 dB，检测、合并再截频；实验室与城区5.8 GHz每段2–4带正常，城区2.4 GHz却因WiFi交错并为60–68 MHz。'),('③ 依据','Basak用YOLO-lite定位暗室叠加信号。按频点同开同关切分只有摘要旁证，尚未在城区WiFi验证。'),('⑤ 结果与留下的问题','调研21个公开集后选NIST（30 MS/s），按字节范围下载。→ 待频带切分后重训。')]
}
TITLES={3:'研究目标：模型究竟凭什么判断？',4:'文献反例决定我们的评测原则',5:'技术路线：九个问题逐步排除捷径',7:'周期性漏检：10 ms 窗口抓不到突发',8:'位置捷径：M300 记住的是信号频率',10:'先审核再训练：处理实测数据问题',11:'本振谱线可能变成标签线索',12:'训练前发现：来源与标签几乎一一对应',13:'第一轮训练：WiFi 被当成背景线索',14:'缺少同接收机背景：用空闲频段镜像',15:'WiFi 怎么补：干扰必须对称叠加',16:'长窗提高召回，虚警却不能直接比较',17:'IQ 特征融合前，先查文献与检验来源',18:'融合未稳定提升，5.8 GHz 反而下降',19:'进行中：按信号所在频带截取',21:'阶段成果：知道分数是怎么来的',22:'创新点：方法、差异与实验证据',23:'仍待解决的问题与下一步'}
